"use client";

import { motion } from "framer-motion";
import { FiArrowRight } from "react-icons/fi";
import { lazy, Suspense, useEffect, useRef, useState } from "react";
import Link from "next/link";
import HeroSlide from "./HeroSlide";

const HeroSlider = lazy(() => import("./HeroSlider"));

const MotionLink = motion.create(Link);

// Each slide has 640/1280/1920px WebP variants generated by scripts/resize-images.mjs.
const heroImages = [
  {
    base: "/images/hero/team",
    width: 1920,
    height: 1080,
    alt: "Diverse tech team collaborating",
    overlayText: "Expert Teams Delivering Excellence",
  },
  {
    base: "/images/hero/data",
    width: 1920,
    height: 1080,
    alt: "Modern data center infrastructure",
    overlayText: "Robust Infrastructure Solutions",
  },
  {
    base: "/images/hero/developer",
    width: 1920,
    height: 1080,
    alt: "Developer coding on advanced setup",
    overlayText: "Cutting-Edge Software Development",
  },
  {
    base: "/images/hero/network",
    width: 1920,
    height: 1280,
    alt: "Global network connections",
    overlayText: "Seamless Network Integration",
  },
  {
    base: "/images/hero/padlock",
    width: 1920,
    height: 1080,
    alt: "Digital security protection",
    overlayText: "Enterprise-Grade Security",
  },
  {
    base: "/images/hero/holographic",
    width: 1920,
    height: 1080,
    alt: "Futuristic holographic interface",
    overlayText: "Innovative Tech Solutions",
  },
];

// Wait for the window load event, then for an idle moment, before starting the slider.
function whenPageIdle(callback) {
  let idleId;
  let timeoutId;
  const schedule = () => {
    if ("requestIdleCallback" in window) idleId = window.requestIdleCallback(callback);
    else timeoutId = window.setTimeout(callback, 200);
  };
  if (document.readyState === "complete") schedule();
  else window.addEventListener("load", schedule, { once: true });
  return () => {
    window.removeEventListener("load", schedule);
    if (idleId !== undefined) window.cancelIdleCallback(idleId);
    if (timeoutId !== undefined) window.clearTimeout(timeoutId);
  };
}

export default function Hero() {
  // false on the server and on the first client render, so hydration matches.
  const [sliderWanted, setSliderWanted] = useState(false);
  // The static first slide stays underneath until the slider first changes slide.
  const [sliderShowing, setSliderShowing] = useState(false);
  const swiperRef = useRef(null);

  useEffect(() => {
    // Autoplay is a looping animation: visitors who prefer reduced motion keep the static first slide.
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return undefined;
    return whenPageIdle(() => setSliderWanted(true));
  }, []);

  return (
    <section className="relative bg-dark text-white min-h-screen flex items-center overflow-hidden">
      {/* Background: first slide as a static image, then the deferred slider on top */}
      <div className="absolute inset-0 z-0">
        {!sliderShowing && (
          <div className="absolute inset-0">
            <HeroSlide slide={heroImages[0]} priority />
          </div>
        )}
        {sliderWanted && (
          <div className="absolute inset-0">
            <Suspense fallback={null}>
              <HeroSlider
                slides={heroImages}
                onSwiper={(swiper) => {
                  swiperRef.current = swiper;
                }}
                onFirstChange={() => setSliderShowing(true)}
              />
            </Suspense>
          </div>
        )}
      </div>

      {/* Content Container */}
      <motion.div 
        initial={{ y: 50 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.8 }}
        className="container mx-auto px-6 py-24 relative z-20"
      >
        <div className="max-w-2xl">
          <h1 className="text-5xl md:text-7xl font-bold mb-6 leading-tight">
            <span className="text-primary">Infyta</span> – Limitless Tech Solutions
          </h1>
          <p className="text-xl md:text-2xl mb-8 opacity-90">
          Engineering Tomorrow’s Tech Today
          </p>
          <div className="flex flex-col sm:flex-row gap-4">
            <MotionLink
              href="/contact"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              className="bg-primary hover:bg-secondary px-8 py-3 rounded-full font-bold flex items-center justify-center gap-2 shadow-lg"
            >
              Get Started <FiArrowRight />
            </MotionLink>
            <MotionLink
              href="/services"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              className="text-center bg-transparent border-2 border-white hover:border-primary text-white hover:text-primary px-8 py-3 rounded-full font-bold"
            >
              Explore Solutions
            </MotionLink>
          </div>
        </div>
      </motion.div>

      {/* Slider Pagination (custom style) */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-20 flex gap-2">
        {heroImages.map((image, index) => (
          <div 
            key={image.base}
            className="h-2 w-2 rounded-full bg-white/50 hover:bg-white cursor-pointer swiper-pagination-bullet"
            onClick={() => swiperRef.current?.slideToLoop(index)}
          />
        ))}
      </div>
    </section>
  );
}